#!/usr/bin/env node
/**
 * Generates api-config.js used by the Ace Tracker frontend.
 *
 * The production push/API backend lives on a separate host (for example
 * Render) while this frontend is served from Vercel. The frontend needs to
 * know that backend's base URL at build time.
 *
 *   VITE_API_URL = "https://your-backend.example.com"
 *
 * If VITE_API_URL is unset, the generated file leaves the URL null and
 * script.js falls back to the same-origin path (/api) which is correct for
 * local development or a single-node deployment.
 *
 * The output file (api-config.js) is gitignored and generated on every build,
 * so no URL or secret is ever committed.
 */
const fs = require("fs");
const path = require("path");

const ROOT = path.resolve(__dirname, "..");
const OUT = path.join(ROOT, "api-config.js");

const apiUrl = (process.env.VITE_API_URL || "").trim();

let value = "null";
if (apiUrl) {
    if (!/^https?:\/\//i.test(apiUrl)) {
        throw new Error(`VITE_API_URL must start with http:// or https:// (got "${apiUrl}")`);
    }
    value = JSON.stringify(apiUrl);
}

const banner = [
    "/* Generated by scripts/gen-api-config.js — do not edit. */",
    `/* VITE_API_URL=${apiUrl || "(unset -> same-origin /api)"} */`,
    `window.ACE_API_URL = ${value};`,
    ""
].join("\n");

fs.writeFileSync(OUT, banner, "utf8");
console.log(`api-config.js written (ACE_API_URL=${apiUrl || "null / same-origin"})`);
